content.text:
{
  "name": "Sensirion 传感器桥接器",
  "name_en": "Sensirion Sensor Bridge",
  "manufacturer": "Sensirion",
  "description": "一款通过 USB 连接电脑并提供双路 I2C 端口的硬件桥接设备，用于在实验中接入、配置和通信 Sensirion 或其他兼容 I2C 的传感器模块，便于传感器测试、数据采集与调试。",
  "description_en": "A hardware USB-to-I2C bridge that connects to a computer and exposes two I2C ports for laboratory communication with Sensirion and other compatible I2C sensor modules, enabling sensor setup, testing, data acquisition, and debugging.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化传感器桥接器并建立通信连接。",
      "description_en": "Initialize the sensor bridge and establish communication."
    },
    {
      "action_name": "auto-setup_i2c_device",
      "description": "配置指定桥接口的 I2C 设备参数，如供电电压和总线频率。",
      "description_en": "Configure an I2C device on the selected bridge port, including supply voltage and bus frequency."
    },
    {
      "action_name": "auto-disable_i2c_device",
      "description": "禁用指定桥接口上的 I2C 设备。",
      "description_en": "Disable the I2C device on the selected bridge port."
    },
    {
      "action_name": "auto-print_i2c_device_information",
      "description": "输出 I2C 设备的信息以便识别和调试。",
      "description_en": "Print information about the I2C device for identification and debugging."
    },
    {
      "action_name": "auto-read_i2c",
      "description": "向指定 I2C 地址发送命令并读取返回字节数据。",
      "description_en": "Send a command to the specified I2C address and read back response bytes."
    },
    {
      "action_name": "auto-write_i2c",
      "description": "向指定 I2C 地址写入命令或数据。",
      "description_en": "Write a command or data payload to the specified I2C address."
    },
    {
      "action_name": "auto-close",
      "description": "关闭桥接器连接并释放通信资源。",
      "description_en": "Close the bridge connection and release communication resources."
    }
  ],
  "tag_hints": [
    "USB-to-I2C bridge",
    "Sensirion sensors",
    "I2C communication",
    "sensor interfacing",
    "dual I2C ports",
    "sensor testing",
    "data acquisition"
  ]
}

